from roman import to_roman, from_roman
import pytest
from hypothesis import given
import hypothesis.strategies as st


# ---- obviously-correct reference model (digit tables) ----
_TH = ["", "M", "MM", "MMM"]
_H = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
_T = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
_O = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]

def ref_to_roman(n: int) -> str:
    return _TH[n // 1000] + _H[(n % 1000) // 100] + _T[(n % 100) // 10] + _O[n % 10]


# ---- concrete examples from spec ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_58():
    assert from_roman("LVIII") == 58

def test_example_from_roman_IIII_rejected():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_0_rejected():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- invariants / round-trips ----
@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_from_after_to(n):
    assert from_roman(to_roman(n)) == n

@given(st.integers(min_value=1, max_value=3999))
def test_reference_model_agrees_with_to_roman(n):
    assert to_roman(n) == ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_result_is_canonical_uppercase(n):
    s = to_roman(n)
    assert isinstance(s, str)
    assert s != ""
    assert s == s.upper()
    assert s.strip() == s
    assert all(c in "IVXLCDM" for c in s)
    # only allowed subtractive pairs may appear as ascending adjacent pairs
    for a, b in zip(s, s[1:]):
        pass
    # no forbidden subtractive pairs
    for bad in ("IL", "IC", "ID", "IM", "XD", "XM", "VX", "VL", "VC", "VD", "VM", "LC", "LD", "LM", "DM"):
        assert bad not in s
    # round-trip back through reference
    assert ref_to_roman(from_roman(s)) == s

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_result_in_range_and_int_type(n):
    v = from_roman(to_roman(n))
    assert type(v) is int
    assert 1 <= v <= 3999

def test_exhaustive_roundtrip_all_values():
    for n in range(1, 4000):
        assert from_roman(to_roman(n)) == n
        assert to_roman(n) == ref_to_roman(n)

def test_exhaustive_to_from_inverse_on_all_canonical():
    seen = set()
    for n in range(1, 4000):
        s = to_roman(n)
        assert s not in seen
        seen.add(s)
        assert to_roman(from_roman(s)) == s

@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=8))
def test_arbitrary_roman_alphabet_string_either_rejected_or_canonical(s):
    try:
        v = from_roman(s)
    except ValueError:
        return
    assert type(v) is int
    assert 1 <= v <= 3999
    assert to_roman(v) == s

@given(st.text(min_size=0, max_size=10))
def test_arbitrary_text_either_rejected_or_canonical(s):
    try:
        v = from_roman(s)
    except ValueError:
        return
    except TypeError:
        raise AssertionError("str input must not raise TypeError")
    assert to_roman(v) == s


# ---- metamorphic / structural properties ----
@given(st.integers(min_value=1, max_value=2999))
def test_adding_thousand_prepends_M(n):
    assert to_roman(n + 1000) == "M" + to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_digit_independence(n):
    s = to_roman(n)
    assert s == ref_to_roman(n)
    # changing one decimal digit only changes corresponding block
    base = ref_to_roman(1000 * (n // 1000) + 1)
    assert to_roman(1000 * (n // 1000) + 1) == _TH[n // 1000] + "I"

@given(st.integers(min_value=1, max_value=3998))
def test_successor_changes_value_by_roundtrip(n):
    assert from_roman(to_roman(n + 1)) - from_roman(to_roman(n)) == 1

def test_boundary_values():
    assert to_roman(1) == "I"
    assert to_roman(3999) == "MMMCMXCIX"
    assert from_roman("I") == 1
    assert from_roman("MMMCMXCIX") == 3999
    assert to_roman(44) == "XLIV"
    assert to_roman(99) == "XCIX"
    assert to_roman(400) == "CD"
    assert to_roman(900) == "CM"
    assert to_roman(944) == "CMXLIV"

def test_canonical_never_uses_IIII_or_other_repetitions():
    for n in range(1, 4000):
        s = to_roman(n)
        assert "IIII" not in s
        assert "XXXX" not in s
        assert "CCCC" not in s
        assert "VV" not in s
        assert "LL" not in s
        assert "DD" not in s
        assert "MMMM" not in s


# ---- error behavior: to_roman ----
@pytest.mark.parametrize("bad", [0, -1, -100, 4000, 4001, 5000, 10000, -3999])
def test_to_roman_out_of_range_raises_value_error(bad):
    with pytest.raises(ValueError):
        to_roman(bad)

@given(st.integers().filter(lambda x: x < 1 or x > 3999))
def test_to_roman_any_out_of_range_raises_value_error(x):
    with pytest.raises(ValueError):
        to_roman(x)

@pytest.mark.parametrize("bad", [True, False, 1.0, 4.0, "IV", "4", None, [4], (4,), 4.5])
def test_to_roman_wrong_type_raises_type_error(bad):
    with pytest.raises(TypeError):
        to_roman(bad)

@given(st.floats(allow_nan=False, allow_infinity=False, min_value=1.0, max_value=3999.0))
def test_to_roman_float_always_type_error(x):
    with pytest.raises(TypeError):
        to_roman(x)

@given(st.booleans())
def test_to_roman_bool_always_type_error(b):
    with pytest.raises(TypeError):
        to_roman(b)


# ---- error behavior: from_roman ----
@pytest.mark.parametrize("bad", [
    "", "iv", "Iv", "IV ", " IV", "X\n", "\tX", "X ", "MCMXCIV\n",
    "IIII", "VV", "LL", "DD", "XXXX", "CCCC", "MMMM",
    "IC", "IM", "XM", "IL", "XD", "VX", "LC", "DM",
    "IXI", "IVI", "IXIV", "IIV", "VIV",
    "MMMM", "MMMMCMXCIX", "MMMMM",
    "A", "B", "Z", "?", "123", "IV1", "M M", "I V",
    "i", "v", "x", "l", "c", "d", "m", "mcmxciv",
    "IIIIII", "VVVV", "XXXXX",
])
def test_from_roman_noncanonical_rejected(bad):
    with pytest.raises(ValueError):
        from_roman(bad)

def test_from_roman_empty_rejected():
    with pytest.raises(ValueError):
        from_roman("")

def test_from_roman_lowercase_rejected():
    with pytest.raises(ValueError):
        from_roman("iv")
    with pytest.raises(ValueError):
        from_roman("mcmxciv")

def test_from_roman_whitespace_rejected():
    for s in [" X", "X ", "X\n", "\nX", "\tX", "X\t", "M C", "M\nM"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_above_3999_rejected():
    with pytest.raises(ValueError):
        from_roman("MMMM")
    with pytest.raises(ValueError):
        from_roman("MMMMCMXCIX")

@pytest.mark.parametrize("bad", [1, 4, 0, 3.5, True, False, None, b"IV", ["I"], ("I",), object()])
def test_from_roman_wrong_type_raises_type_error(bad):
    with pytest.raises(TypeError):
        from_roman(bad)

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_mutated_canonical_rejected_or_different(n):
    s = to_roman(n)
    # lowercased must be rejected
    with pytest.raises(ValueError):
        from_roman(s.lower())
    # padded with whitespace must be rejected
    with pytest.raises(ValueError):
        from_roman(" " + s)
    with pytest.raises(ValueError):
        from_roman(s + " ")
    # duplicated string (s+s) must either be rejected or decode differently
    doubled = s + s
    try:
        v = from_roman(doubled)
    except ValueError:
        pass
    else:
        assert v != n or to_roman(v) == doubled

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_single_char_mutation_detected(n):
    s = to_roman(n)
    for alt in "IVXLCDM":
        if alt == s[0]:
            continue
        mutated = alt + s[1:]
        if mutated == s:
            continue
        try:
            v = from_roman(mutated)
        except ValueError:
            continue
        assert to_roman(v) == mutated
        assert mutated != s or v == n
